export const WISDOM_EXTRA_SUFISM: WisdomArchetype[] = [
  { concept: "The Beloved — Ishq", tradition: "Sufism", source: "Rumi, Masnavi 1.1-1.5", explanation: "Sufism's central term: ishq — the love that is not a feeling but a force, the love that consumes the lover. Rumi's opening of the Masnavi: the reed flute's cry is the soul's separation from the Beloved. The teaching's precision: love is not an emotion among emotions but the structure of reality.", application: "Use ishq as the library's love-teaching: in any attachment, ask 'is this love or possession?' The application is the love's recognition — the love that consumes the lover, not the love that consumes the loved.", questions: ["Where is my love — and is it love or possession?", "What is the difference between the love that consumes the lover and the love that consumes the loved?", "Can I hold ishq as structure, not as feeling?"], references: ["Rumi, Masnavi 1.1-1.5", "Rumi, Divan-e Shams", "Ibn Arabi, Fusus al-Hikam"], excerpt: "The reed flute's cry is the soul's separation from the Beloved. Love is the structure of reality.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti", "sufi"], domains: ["spirituality", "relationships"], tags: ["sufism", "ishq", "beloved", "love", "force", "structure", "rumi", "separation"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Guest House — Rumi's Welcome", tradition: "Sufism", source: "Rumi, The Guest House (Mathnawi)", explanation: "Rumi's famous poem: this being is a guest house; every emotion a visitor. The teaching's precision: the host does not choose the guests — the guests arrive, are welcomed, and depart. The host's job is not selection but reception. The poem's final line: 'Be grateful for whoever comes, because each has been sent as a guide from beyond.'", application: "Use the guest house as the library's hospitality teaching: in any emotion, welcome it. The application is the welcome's practice — not the emotion's indulgence but the host's reception.", questions: ["What guest is in my house right now — and am I welcoming it?", "What is the difference between welcoming (reception) and indulging (obeying)?", "Can I be grateful for the guest — not as sentiment but as practice?"], references: ["Rumi, The Guest House (from Mathnawi, Book 6)", "Rumi, Masnavi", "Rumi, Divan-e Shams"], excerpt: "This being is a guest house. Every emotion is a visitor. Be grateful for whoever comes.", evidence: "traditional", dimensions: ["emotion", "spirit"], paths: ["bhakti", "sufi"], domains: ["growth", "self_care"], tags: ["sufism", "guest_house", "rumi", "welcome", "reception", "emotion", "visitor", "guide"], difficulty: "beginner", minutes: 5 },
  { concept: "Fana — The Annihilation of the Ego", tradition: "Sufism", source: "Ibn Arabi, Fusus al-Hikam; Rumi, Masnavi", explanation: "Fana — the annihilation of the ego's selfhood in the divine. The teaching's precision: not the ego's destruction but its transparency — the ego becomes a window, not a wall. The fana is not the self's death but the self's recognition as the divine's instrument.", application: "Use fana as the library's ego-teaching: in any self-assertion, ask 'is this the ego's wall or the divine's window?' The application is the transparency's cultivation — not the self's destruction but the self's reclassification.", questions: ["Where is my ego a wall — and where could it be a window?", "What is the difference between annihilation (destruction) and transparency (reclassification)?", "Can I hold the self as instrument — not as owner?"], references: ["Ibn Arabi, Fusus al-Hikam", "Rumi, Masnavi (throughout)", "Al-Ghazali, Ihya Ulum al-Din"], excerpt: "Fana — the ego's annihilation. Not destruction but transparency: the ego becomes a window.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti", "sufi"], domains: ["spirituality", "growth"], tags: ["sufism", "fana", "annihilation", "ego", "transparency", "window", "ibn_arabi", "rumi"], difficulty: "advanced", minutes: 8 },
  { concept: "Baqa — The Subsistence in the Divine", tradition: "Sufism", source: "Ibn Arabi, Fusus al-Hikam; Rumi", explanation: "Baqa — the subsistence in the divine, after fana. The teaching's precision: fana (annihilation) is not the end but the beginning — the ego's annihilation reveals the divine's subsistence, which is the self's true subsistence. The baqa is not the self's survival but the divine's life, recognized as one's own.", application: "Use baqa as the library's subsistence teaching: in any survival-anxiety, ask 'whose life is this?' The application is the recognition — not the self's survival but the divine's life, recognized.", questions: ["Where is my survival-anxiety — and whose life is it?", "What is the difference between survival (self) and subsistence (divine)?", "Can I recognize the divine's life as my own?"], references: ["Ibn Arabi, Fusus al-Hikam", "Rumi, Masnavi (throughout)", "Al-Ghazali, Ihya Ulum al-Din"], excerpt: "Baqa — the subsistence in the divine, after fana. The divine's life, recognized as one's own.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["bhakti", "sufi"], domains: ["spirituality", "growth"], tags: ["sufism", "baqa", "subsistence", "fana", "survival", "divine", "ibn_arabi", "rumi"], difficulty: "advanced", minutes: 8 },
  { concept: "Wahdat al-Wujud — The Unity of Being", tradition: "Sufism", source: "Ibn Arabi, Fusus al-Hikam; Rumi", explanation: "Ibn Arabi's doctrine: wahdat al-wujud — the unity of being. The teaching's precision: not that all things are one (pantheism) but that the divine being is the only being, and all things are its manifestations. The distinction between the divine and the world is the distinction between the ocean and the wave — real but not absolute.", application: "Use wahdat al-wujud as the library's non-dual teaching: in any separation, ask 'is this separation absolute?' The application is the separation's recognition — real but not absolute, like the ocean and the wave.", questions: ["Where is my separation — and is it absolute?", "What is the difference between pantheism (all is one) and wahdat al-wujud (one being, many manifestations)?", "Can I hold the separation as real but not absolute?"], references: ["Ibn Arabi, Fusus al-Hikam", "Ibn Arabi, Al-Futuhat al-Makkiyya", "Rumi, Masnavi"], excerpt: "Wahdat al-wujud — the unity of being. One being, many manifestations. Real but not absolute.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["sufi", "jnana"], domains: ["spirituality", "learning"], tags: ["sufism", "wahdat_al_wujud", "unity_of_being", "ibn_arabi", "manifestation", "ocean", "wave", "non_dual"], difficulty: "advanced", minutes: 9 },
  { concept: "The Perfect Human — Insan al-Kamil", tradition: "Sufism", source: "Ibn Arabi, Fusus al-Hikam", explanation: "Ibn Arabi's teaching: the insan al-kamil — the perfect human — is the microcosm of the divine, the point at which the divine's self-knowledge is most complete. The teaching's precision: the perfect human is not perfect in the moral sense but in the ontological — the one in whom the divine's attributes are most fully manifested.", application: "Use the insan al-kamil as the library's human-potential teaching: the human is the divine's most complete mirror. The application is the mirror's recognition — not the human's perfection but the divine's self-knowledge, recognized in the human.", questions: ["Where is my humanity — and is it a mirror of the divine?", "What is the difference between moral perfection and ontological perfection?", "Can I recognize the divine's self-knowledge in my own humanity?"], references: ["Ibn Arabi, Fusus al-Hikam", "Ibn Arabi, Al-Futuhat al-Makkiyya", "Rumi, Masnavi"], excerpt: "The perfect human — the microcosm of the divine, the point of complete self-knowledge.", evidence: "traditional", dimensions: ["spirit", "thought", "connection"], paths: ["sufi", "bhakti"], domains: ["spirituality", "growth"], tags: ["sufism", "insan_al_kamil", "perfect_human", "microcosm", "ibn_arabi", "self_knowledge", "divine"], difficulty: "advanced", minutes: 9 },
  { concept: "The Stations — Maqamat", tradition: "Sufism", source: "Al-Ghazali, Ihya Ulum al-Din; Sufi tradition", explanation: "The Sufi teaching on the maqamat — the stations of the path: repentance, abstinence, renunciation, poverty, patience, gratitude, hope, fear, love, contentment. The teaching's precision: the stations are not stages (sequential) but qualities (simultaneous) — each is cultivated, not achieved.", application: "Use the maqamat as the library's character curriculum: each station is a quality to cultivate, not a stage to achieve. The application is the quality's practice — not the station's arrival but the quality's cultivation.", questions: ["Which station (quality) is strongest in me — and which is absent?", "What is the difference between a station (achieved) and a quality (cultivated)?", "Can I cultivate the absent quality — without demanding its arrival?"], references: ["Al-Ghazali, Ihya Ulum al-Din", "Sufi tradition manuals", "Rumi, Masnavi"], excerpt: "The stations — repentance, abstinence, renunciation, poverty, patience, gratitude, hope, fear, love, contentment.", evidence: "traditional", dimensions: ["emotion", "action", "spirit"], paths: ["sufi", "bhakti"], domains: ["growth", "spirituality"], tags: ["sufism", "maqamat", "stations", "qualities", "cultivation", "al_ghazali", "path"], difficulty: "intermediate", minutes: 8 },
  { concept: "The Remembrance — Dhikr", tradition: "Sufism", source: "Sufi tradition; Quran 33:41", explanation: "Dhikr — the remembrance of God, the repetition of the divine names. The teaching's precision: dhikr is not the mind's occupation but the heart's alignment — the names are repeated until the name and the named are one. The dhikr's purpose is not the repetition but the recognition.", application: "Use dhikr as the library's remembrance teaching: in any repetition practice, ask 'is this occupation or alignment?' The application is the alignment's recognition — not the name's repetition but the named's presence.", questions: ["Where is my repetition occupation — and where is it alignment?", "What is the difference between the name's repetition and the named's presence?", "Can I hold the dhikr as alignment — not as occupation?"], references: ["Quran 33:41", "Sufi tradition manuals", "Rumi, Masnavi"], excerpt: "Dhikr — the remembrance. The names are repeated until the name and the named are one.", evidence: "traditional", dimensions: ["spirit", "thought", "emotion"], paths: ["sufi", "bhakti"], domains: ["spirituality", "growth"], tags: ["sufism", "dhikr", "remembrance", "repetition", "alignment", "occupation", "names", "quran"], difficulty: "beginner", minutes: 6 },
  { concept: "The Heart — The Qalb", tradition: "Sufism", source: "Sufi tradition; Al-Ghazali, Ihya", explanation: "The qalb — the heart, the Sufi's primary organ of knowledge. The teaching's precision: the heart is not the emotion but the knowing — the faculty that perceives the divine. The heart's polishing (tazkiya) is the practice's core — the heart's mirror is cleaned until it reflects the divine.", application: "Use the qalb as the library's heart-teaching: in any perception, ask 'is this the mind's knowing or the heart's?' The application is the heart's recognition — not the mind's concept but the heart's perception.", questions: ["Where is my knowing the mind's — and where the heart's?", "What is the difference between the mind's concept and the heart's perception?", "Can I cultivate the heart's knowing — the heart's mirror?"], references: ["Al-Ghazali, Ihya Ulum al-Din", "Sufi tradition manuals", "Rumi, Masnavi"], excerpt: "The qalb — the heart, the organ of knowing. The mirror polished until it reflects the divine.", evidence: "traditional", dimensions: ["spirit", "emotion", "thought"], paths: ["sufi", "bhakti"], domains: ["spirituality", "growth"], tags: ["sufism", "qalb", "heart", "knowing", "mirror", "polishing", "tazkiya", "al_ghazali"], difficulty: "intermediate", minutes: 7 },
  { concept: "The Polishing — Tazkiya", tradition: "Sufism", source: "Sufi tradition; Quran 91:9", explanation: "Tazkiya — the polishing of the heart's mirror. The teaching's precision: the heart is already a mirror — the practice is not the mirror's creation but its polishing. The polishing is the removal of the rust (the ego, the world) that obscures the reflection.", application: "Use tazkiya as the library's purification teaching: in any practice, ask 'is this creating or polishing?' The application is the polishing's recognition — not the mirror's creation but the rust's removal.", questions: ["Where is my practice creating — and where is it polishing?", "What is the rust on my heart's mirror?", "Can I polish — not create — and let the reflection appear?"], references: ["Quran 91:9", "Sufi tradition manuals", "Al-Ghazali, Ihya Ulum al-Din"], excerpt: "Tazkiya — the polishing. The mirror is already there; the rust is removed.", evidence: "traditional", dimensions: ["spirit", "emotion", "thought"], paths: ["sufi", "bhakti"], domains: ["spirituality", "growth"], tags: ["sufism", "tazkiya", "polishing", "mirror", "rust", "purification", "quran", "al_ghazali"], difficulty: "intermediate", minutes: 7 },
];

export const WISDOM_EXTRA_MYSTICISM: WisdomArchetype[] = [
  { concept: "The Cloud of Unknowing — The Way to God", tradition: "Mysticism", source: "The Cloud of Unknowing (14th century)", explanation: "The Cloud of Unknowing's teaching: God cannot be known by the intellect but only by love. The teaching's precision: the 'cloud of unknowing' is not ignorance but the mind's limit — beyond it, the heart's love reaches what the mind cannot. The method: a single word (like 'God' or 'love') repeated in the heart, not the mind.", application: "Use the cloud as the library's apophatic teaching: in any seeking, ask 'am I knowing or loving?' The application is the love's practice — not the mind's understanding but the heart's reaching.", questions: ["Where is my seeking knowing — and where is it loving?", "What is the difference between the mind's knowing and the heart's reaching?", "Can I hold the cloud of unknowing — not as failure but as the way?"], references: ["The Cloud of Unknowing", "The Book of Privy Counselling", "Walter Hilton, Scale of Perfection"], excerpt: "God cannot be known by the intellect but only by love. The cloud of unknowing is the way.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti", "mystic"], domains: ["spirituality", "learning"], tags: ["mysticism", "cloud_of_unknowing", "apophatic", "love", "intellect", "heart", "reaching", "14th_century"], difficulty: "advanced", minutes: 8 },
  { concept: "The Dark Night of the Soul — St. John of the Cross", tradition: "Mysticism", source: "St. John of the Cross, Dark Night of the Soul", explanation: "St. John of the Cross's teaching: the dark night of the soul — the period when the spiritual life's consolations are withdrawn, and the practitioner is left in dryness. The teaching's precision: the dark night is not depression but purification — the soul's detachment from its own spiritual experiences, so that it may be united with God alone.", application: "Use the dark night as the library's purification teaching: in any dryness, ask 'is this depression or purification?' The application is the dryness's recognition — not the consolations' pursuit but the soul's detachment.", questions: ["Where is my dryness — depression or purification?", "What is the difference between the consolation (spiritual experience) and the union (God alone)?", "Can I hold the dark night — not as loss but as purification?"], references: ["St. John of the Cross, Dark Night of the Soul", "St. John of the Cross, Ascent of Mount Carmel", "Teresa of Avila, Interior Castle"], excerpt: "The dark night is not depression but purification — the soul's detachment from its own spiritual experiences.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti", "mystic"], domains: ["spirituality", "growth"], tags: ["mysticism", "dark_night", "st_john_of_cross", "purification", "dryness", "consolation", "union", "16th_century"], difficulty: "advanced", minutes: 9 },
  { concept: "The Interior Castle — Teresa of Avila", tradition: "Mysticism", source: "Teresa of Avila, Interior Castle", explanation: "Teresa of Avila's teaching: the soul is a castle with seven mansions, each deeper than the last. The teaching's precision: the mansions are not places but states — the progressive deepening of the soul's union with God. The seventh mansion is the spiritual marriage, the union's completion.", application: "Use the interior castle as the library's depth teaching: in any practice, ask 'which mansion am I in?' The application is the depth's recognition — not the mansion's achievement but the soul's location.", questions: ["Which mansion is my soul in — and what is its depth?", "What is the difference between the mansion (state) and the union (goal)?", "Can I hold the castle's depth — not as achievement but as location?"], references: ["Teresa of Avila, Interior Castle", "Teresa of Avila, The Way of Perfection", "St. John of the Cross, Dark Night"], excerpt: "The soul is a castle with seven mansions, each deeper than the last.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["bhakti", "mystic"], domains: ["spirituality", "growth"], tags: ["mysticism", "interior_castle", "teresa_of_avila", "mansions", "depth", "union", "spiritual_marriage", "16th_century"], difficulty: "advanced", minutes: 9 },
  { concept: "Meister Eckhart — The Ground of the Soul", tradition: "Mysticism", source: "Meister Eckhart, Sermons and Treatises", explanation: "Meister Eckhart's teaching: the ground of the soul (Seelengrund) — the soul's deepest point, where it touches the divine's ground. The teaching's precision: the ground is not a place but a recognition — the soul's identity with the divine's ground, recognized. The ground is the soul's original nature, not its achievement.", application: "Use the ground as the library's depth teaching: in any depth, ask 'am I going deeper or recognizing the ground?' The application is the ground's recognition — not the depth's achievement but the ground's reception.", questions: ["Where is my depth — achievement or recognition?", "What is the difference between the soul's ground (original) and the soul's achievement (acquired)?", "Can I recognize the ground — not as depth but as nature?"], references: ["Meister Eckhart, Sermons", "Meister Eckhart, Treatises", "The German Mystics"], excerpt: "The ground of the soul — the soul's deepest point, where it touches the divine's ground.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["bhakti", "mystic", "jnana"], domains: ["spirituality", "learning"], tags: ["mysticism", "eckhart", "ground", "soul", "recognition", "original", "depth", "german_mystics"], difficulty: "advanced", minutes: 9 },
  { concept: "The Apophatic Way — The Way of Negation", tradition: "Mysticism", source: "Pseudo-Dionysius, Mystical Theology", explanation: "The apophatic way — the way of negation, the via negativa. The teaching's precision: God is not known by what God is but by what God is not. The method: negate every attribute, every concept, every name — until what remains is not a concept but the divine's presence, known by unknowing.", application: "Use the apophatic way as the library's negation teaching: in any concept of the divine, negate it. The application is the negation's practice — not the concept's destruction but the concept's transcendence.", questions: ["Where is my concept of the divine — and can I negate it?", "What is the difference between negation (transcendence) and denial (rejection)?", "Can I hold the apophatic way — not as ignorance but as the way?"], references: ["Pseudo-Dionysius, Mystical Theology", "Meister Eckhart, Sermons", "The Cloud of Unknowing"], excerpt: "God is known by what God is not. The apophatic way — negation as the path to presence.", evidence: "traditional", dimensions: ["spirit", "thought"], paths: ["mystic", "jnana"], domains: ["spirituality", "learning"], tags: ["mysticism", "apophatic", "via_negativa", "negation", "pseudo_dionysius", "transcendence", "unknowing"], difficulty: "advanced", minutes: 9 },
  { concept: "The Spiritual Marriage — The Seventh Mansion", tradition: "Mysticism", source: "Teresa of Avila, Interior Castle, Seventh Mansion", explanation: "The spiritual marriage — the seventh mansion's union. The teaching's precision: the union is not the soul's absorption (loss) but the soul's marriage (recognition) — two become one, but neither is lost. The marriage's completion is the soul's union with God, in which the soul's identity is not erased but fulfilled.", application: "Use the spiritual marriage as the library's union teaching: in any union-experience, ask 'is this absorption (loss) or marriage (recognition)?' The application is the recognition's holding — not the identity's erasure but the identity's fulfillment.", questions: ["Where is my union — absorption or marriage?", "What is the difference between the soul's absorption (loss) and the soul's marriage (fulfillment)?", "Can I hold the union as fulfillment — not as erasure?"], references: ["Teresa of Avila, Interior Castle, Seventh Mansion", "Teresa of Avila, The Way of Perfection", "St. John of the Cross, Dark Night"], excerpt: "The spiritual marriage — two become one, but neither is lost. Fulfillment, not erasure.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["mystic", "bhakti"], domains: ["spirituality"], tags: ["mysticism", "spiritual_marriage", "union", "teresa_of_avila", "fulfillment", "erasure", "seventh_mansion"], difficulty: "advanced", minutes: 9 },
  { concept: "The Mystic's Closing — The Love That Remains", tradition: "Mysticism", source: "Teresa of Avila, Interior Castle; St. John of the Cross", explanation: "The mystic's closing: after the union, the love that remains — the soul's love for God, transformed by the union, is the fruit of the path. The teaching's precision: the love is not the same love as before the union — it is the union's fruit, the love that remains after the union. The closing is the teaching's final image.", application: "Use the closing as the library's fruit teaching: in any practice's completion, ask 'what love remains?' The application is the fruit's recognition — not the practice's completion but the love's cultivation.", questions: ["What love remains after my practice's completion?", "What is the difference between the love before (aspiration) and the love after (fruit)?", "Can I hold the fruit's cultivation — the love that remains — as the completion?"], references: ["Teresa of Avila, Interior Castle", "St. John of the Cross, Dark Night", "The Mystic Tradition"], excerpt: "The love that remains — the union's fruit, the practice's completion.", evidence: "traditional", dimensions: ["spirit", "emotion"], paths: ["mystic", "bhakti"], domains: ["spirituality", "growth"], tags: ["mysticism", "closing", "love", "remains", "fruit", "union", "teresa", "john_of_cross"], difficulty: "advanced", minutes: 8 },
];

export const WISDOM_EXTRA_EXISTENTIAL: WisdomArchetype[] = [
  { concept: "Existence Precedes Essence", tradition: "Existential Philosophy", source: "Jean-Paul Sartre, Existentialism Is a Humanism (1946)", explanation: "Sartre's famous formula: existence precedes essence. The teaching's precision: there is no human nature, no predefined essence — the human exists first, then defines itself through its choices. The human is not a thing with a nature but a being whose nature is its freedom.", application: "Use the formula as the library's freedom teaching: in any 'I am X' claim, ask 'is this my essence or my choice?' The application is the choice's recognition — not the nature's discovery but the nature's creation.", questions: ["Where am I treating my choices as my nature?", "What is the difference between discovering essence and creating it?", "Can I hold my freedom — not as a burden but as the reality?"], references: ["Jean-Paul Sartre, Existentialism Is a Humanism", "Jean-Paul Sartre, Being and Nothingness", "Simone de Beauvoir, The Ethics of Ambiguity"], excerpt: "Existence precedes essence. The human is not a thing with a nature but a being whose nature is its freedom.", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["jnana", "karma"], domains: ["growth", "purpose", "learning"], tags: ["existential", "sartre", "existence", "essence", "freedom", "choice", "creation", "humanism"], difficulty: "advanced", minutes: 8 },
  { concept: "Bad Faith — Sartre's Self-Deception", tradition: "Existential Philosophy", source: "Jean-Paul Sartre, Being and Nothingness (1943)", explanation: "Sartre's concept of mauvaise foi — bad faith, self-deception. The teaching's precision: bad faith is not lying to others but lying to oneself — treating oneself as a thing (with a fixed nature) rather than as a freedom. The waiter who plays at being a waiter is in bad faith.", application: "Use bad faith as the library's self-deception teaching: in any 'I am' claim, ask 'is this bad faith?' The application is the claim's examination — not the claim's abandonment but the freedom's recognition.", questions: ["Where am I in bad faith — treating myself as a thing?", "What is the difference between a role (played) and a nature (claimed)?", "Can I hold my freedom — and stop playing at being a thing?"], references: ["Jean-Paul Sartre, Being and Nothingness", "Jean-Paul Sartre, Existentialism Is a Humanism", "Simone de Beauvoir, The Ethics of Ambiguity"], excerpt: "Bad faith — treating oneself as a thing rather than as a freedom. The self-deception of fixed nature.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["jnana"], domains: ["growth", "learning"], tags: ["existential", "sartre", "bad_faith", "mauvaise_foi", "self_deception", "thing", "freedom", "role"], difficulty: "advanced", minutes: 8 },
  { concept: "The Absurd — Camus's Teaching", tradition: "Existential Philosophy", source: "Albert Camus, The Myth of Sisyphus (1942)", explanation: "Camus's concept of the absurd: the confrontation between the human's demand for meaning and the world's silence. The teaching's precision: the absurd is not a property of the world (the world is silent) nor of the human (the human demands meaning) but of their confrontation. The absurd is not a problem to solve but a condition to live.", application: "Use the absurd as the library's meaning-teaching: in any meaninglessness, ask 'is this the world's silence or my demand?' The application is the confrontation's recognition — not the meaning's finding but the absurd's living.", questions: ["Where is my demand for meaning — and where is the world's silence?", "What is the difference between the absurd (confrontation) and meaninglessness (property)?", "Can I live the absurd — not as despair but as defiance?"], references: ["Albert Camus, The Myth of Sisyphus", "Albert Camus, The Rebel", "Albert Camus, The Stranger"], excerpt: "The absurd is the confrontation between the human's demand for meaning and the world's silence.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["jnana", "existential"], domains: ["purpose", "growth", "learning"], tags: ["existential", "camus", "absurd", "meaning", "silence", "demand", "confrontation", "myth_of_sisyphus"], difficulty: "advanced", minutes: 8 },
  { concept: "The Myth of Sisyphus — The Happy Sisyphus", tradition: "Existential Philosophy", source: "Albert Camus, The Myth of Sisyphus", explanation: "Camus's conclusion: 'One must imagine Sisyphus happy.' The teaching's precision: Sisyphus, condemned to roll the boulder forever, is not happy despite the absurd but because of it — the absurd's recognition is the happiness. The happiness is not hope (the boulder will stay) but the struggle itself — 'the struggle itself toward the heights is enough to fill a man's heart.'", application: "Use the happy Sisyphus as the library's resilience teaching: in any repetitive struggle, ask 'is this the struggle or the hope?' The application is the struggle's recognition — not the boulder's arrival but the struggle's sufficiency.", questions: ["Where is my struggle — and is it the struggle or the hope?", "What is the difference between the struggle (sufficient) and the arrival (impossible)?", "Can I imagine Sisyphus happy — and be happy in the struggle?"], references: ["Albert Camus, The Myth of Sisyphus", "Albert Camus, The Rebel", "Albert Camus, Notebooks"], excerpt: "One must imagine Sisyphus happy. The struggle itself toward the heights is enough to fill a man's heart.", evidence: "traditional", dimensions: ["action", "spirit", "emotion"], paths: ["existential", "karma"], domains: ["growth", "work", "purpose"], tags: ["existential", "camus", "sisyphus", "happy", "struggle", "heights", "heart", "resilience"], difficulty: "intermediate", minutes: 7 },
  { concept: "Being-toward-Death — Heidegger's Dasein", tradition: "Existential Philosophy", source: "Martin Heidegger, Being and Time (1927)", explanation: "Heidegger's concept: Sein-zum-Tode — being-toward-death. The teaching's precision: the human (Dasein) is the being that understands its own being, and its being is being-toward-death — not as a future event but as the structure of existence. Death is not the end but the horizon that gives life its urgency and authenticity.", application: "Use being-toward-death as the library's mortality teaching: in any decision, ask 'is this being-toward-death or being-toward-life?' The application is the horizon's recognition — not the death's fear but the life's urgency.", questions: ["Where is my being — toward death or toward life?", "What is the difference between death (horizon) and death (end)?", "Can I hold being-toward-death — not as fear but as urgency?"], references: ["Martin Heidegger, Being and Time", "Martin Heidegger, The Essence of Truth", "Martin Heidegger, What Is Metaphysics?"], excerpt: "Being-toward-death — not as a future event but as the structure of existence.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["existential", "jnana"], domains: ["growth", "purpose", "spirituality"], tags: ["existential", "heidegger", "being_toward_death", "dasein", "horizon", "urgency", "authenticity", "being_and_time"], difficulty: "advanced", minutes: 9 },
  { concept: "The Eternal Return — Nietzsche's Teaching", tradition: "Existential Philosophy", source: "Friedrich Nietzsche, The Gay Science 341; Thus Spoke Zarathustra", explanation: "Nietzsche's concept: the eternal return — the thought experiment: what if every moment of your life recurs, eternally? The teaching's precision: the eternal return is not a cosmological theory but an ethical test — the question 'do you want this moment again?' is the measure of the life's affirmation.", application: "Use the eternal return as the library's affirmation teaching: in any moment, ask 'would I want this again?' The application is the affirmation's recognition — not the moment's perfection but the life's yes.", questions: ["Where is my life a 'yes' — and where is it a 'no'?", "What is the difference between the eternal return (ethical test) and the cosmological theory (speculation)?", "Can I hold the moment's affirmation — not as perfection but as yes?"], references: ["Friedrich Nietzsche, The Gay Science 341", "Friedrich Nietzsche, Thus Spoke Zarathustra", "Friedrich Nietzsche, Ecce Homo"], excerpt: "The eternal return — the ethical test: would you want this moment again?", evidence: "traditional", dimensions: ["thought", "spirit", "action"], paths: ["existential", "karma"], domains: ["growth", "purpose"], tags: ["existential", "nietzsche", "eternal_return", "affirmation", "yes", "moment", "gay_science", "zarathustra"], difficulty: "advanced", minutes: 8 },
  { concept: "The Will to Power — Nietzsche's Drive", tradition: "Existential Philosophy", source: "Friedrich Nietzsche, Beyond Good and Evil; The Will to Power", explanation: "Nietzsche's concept: the will to power — the fundamental drive of all life. The teaching's precision: the will to power is not domination (over others) but self-overcoming (over oneself) — the drive to grow, to create, to become more. The will to power is the life's affirmation, not its aggression.", application: "Use the will to power as the library's growth teaching: in any drive, ask 'is this domination or self-overcoming?' The application is the drive's recognition — not the drive's suppression but the drive's reclassification.", questions: ["Where is my drive domination — and where is it self-overcoming?", "What is the difference between the will to power (growth) and the will to dominate (aggression)?", "Can I hold the will to power — not as aggression but as growth?"], references: ["Friedrich Nietzsche, Beyond Good and Evil", "Friedrich Nietzsche, The Will to Power", "Friedrich Nietzsche, The Gay Science"], excerpt: "The will to power — the drive to grow, to create, to become more. Not domination but self-overcoming.", evidence: "traditional", dimensions: ["action", "thought", "spirit"], paths: ["existential", "karma"], domains: ["growth", "purpose", "work"], tags: ["existential", "nietzsche", "will_to_power", "growth", "self_overcoming", "domination", "aggression", "affirmation"], difficulty: "advanced", minutes: 9 },
  { concept: "The Death of God — Nietzsche's Proclamation", tradition: "Existential Philosophy", source: "Friedrich Nietzsche, The Gay Science 125", explanation: "Nietzsche's proclamation: 'God is dead.' The teaching's precision: not the announcement of atheism but the diagnosis of a cultural condition — the values that were grounded in God have lost their ground. The death of God is not a celebration but a problem: the values must be re-grounded, or nihilism follows.", application: "Use the death of God as the library's values-teaching: in any value, ask 'what is its ground?' The application is the ground's recognition — not the value's rejection but the value's re-examination.", questions: ["Where is my value's ground — and is it still alive?", "What is the difference between the death of God (diagnosis) and atheism (belief)?", "Can I hold the values' re-examination — not as nihilism but as honesty?"], references: ["Friedrich Nietzsche, The Gay Science 125", "Friedrich Nietzsche, Thus Spoke Zarathustra", "Friedrich Nietzsche, The Will to Power"], excerpt: "God is dead — not a celebration but a diagnosis. The values must be re-grounded, or nihilism follows.", evidence: "traditional", dimensions: ["thought", "spirit"], paths: ["existential", "jnana"], domains: ["growth", "purpose", "learning"], tags: ["existential", "nietzsche", "death_of_god", "values", "ground", "nihilism", "re_examination", "gay_science"], difficulty: "advanced", minutes: 8 },
  { concept: "Nihilism — The Crisis of Meaning", tradition: "Existential Philosophy", source: "Friedrich Nietzsche, The Will to Power; Heidegger, Nietzsche", explanation: "Nietzsche's diagnosis: nihilism — the crisis of meaning, the collapse of values. The teaching's precision: nihilism is not a position (nothing matters) but a condition (the values have collapsed). The nihilism's danger is not the collapse but the despair — the despair that follows the collapse when no new values are created.", application: "Use nihilism as the library's crisis-teaching: in any meaning-crisis, ask 'is this nihilism or transition?' The application is the transition's recognition — not the despair's indulgence but the new-values' creation.", questions: ["Where is my meaning-crisis — nihilism or transition?", "What is the difference between the collapse (condition) and the despair (response)?", "Can I hold the transition — and create new values?"], references: ["Friedrich Nietzsche, The Will to Power", "Martin Heidegger, Nietzsche", "Albert Camus, The Myth of Sisyphus"], excerpt: "Nihilism — the crisis of meaning, the collapse of values. The danger is the despair, not the collapse.", evidence: "traditional", dimensions: ["thought", "spirit", "emotion"], paths: ["existential", "jnana"], domains: ["growth", "purpose", "learning"], tags: ["existential", "nietzsche", "nihilism", "meaning", "values", "collapse", "despair", "transition", "heidegger"], difficulty: "advanced", minutes: 9 },
];

